import{c as a,Q as l,j as e,m as d}from"./chunks/framework.DOi4mjdC.js";const s="/assets/NZ2ND%E8%BD%AC%E6%8D%A2%E7%A4%BA%E6%84%8F%E5%9B%BE%EF%BC%88half%E6%95%B0%E6%8D%AE%E7%B1%BB%E5%9E%8B%EF%BC%89.DAap6DUH.png",r="/assets/NZ2ND%E8%BD%AC%E6%8D%A2%E7%A4%BA%E6%84%8F%E5%9B%BE%EF%BC%88float%E6%95%B0%E6%8D%AE%E7%B1%BB%E5%9E%8B%EF%BC%89.Kj9w04Sz.png",b=JSON.parse('{"title":"随路转换NZ2ND搬运","description":"","frontmatter":{},"headers":[{"level":1,"title":"随路转换NZ2ND搬运","slug":"随路转换nz2nd搬运"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"支持的通路和数据类型","slug":"支持的通路和数据类型"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/Memory数据搬运/DataCopy/随路转换NZ2ND搬运.md","filePath":"api/SIMD-API/基础API/Memory数据搬运/DataCopy/随路转换NZ2ND搬运.md"}'),i={name:"api/SIMD-API/基础API/Memory数据搬运/DataCopy/随路转换NZ2ND搬运.md"};function n(o,t,p,h,c,N){return l(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="随路转换nz2nd搬运" tabindex="-1">随路转换NZ2ND搬运 <a class="header-anchor" href="#随路转换nz2nd搬运" aria-label="Permalink to &quot;随路转换NZ2ND搬运&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>支持在数据搬运时进行NZ到ND格式的转换。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T&gt;</span></span>\n<span class="line"><span>__aicore__ inline void DataCopy(const GlobalTensor&lt;T&gt;&amp; dst, const LocalTensor&lt;T&gt;&amp; src, const Nz2NdParamsFull&amp; intriParams)</span></span></code></pre></div><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p>各原型支持的具体数据通路和数据类型，请参考<a href="#section189171223121916">支持的通路和数据类型</a>。</p></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>源操作数或者目的操作数的数据类型。支持的数据类型请参考支持的通路和数据类型。</td></tr></tbody></table><p><strong>表 2</strong> 接口参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数，类型为GlobalTensor。</td></tr><tr><td>src</td><td>输入</td><td>源操作数，类型为LocalTensor。</td></tr><tr><td>intriParams</td><td>输入</td><td>搬运参数，类型为Nz2NdParamsFull。 具体定义请参考${INSTALL_DIR}/include/ascendc/basic_api/interface/kernel_struct_data_copy.h，${INSTALL_DIR}请替换为CANN软件安装后文件存储路径。</td></tr></tbody></table><p><strong>表 3</strong> Nz2NdParamsFull结构体内参数定义</p><table tabindex="0"><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>ndNum</td><td>传输NZ矩阵的数目，取值范围：ndNum∈[0, 4095]。</td></tr><tr><td>nValue</td><td>NZ矩阵的行数，取值范围：nValue∈[1, 8192]。</td></tr><tr><td>dValue</td><td>NZ矩阵的列数，取值范围：dValue∈[1, 8192]。dValue必须为16的倍数。</td></tr><tr><td>srcNdMatrixStride</td><td>源相邻NZ矩阵的偏移（头与头），取值范围：srcNdMatrixStride∈[1, 512]，单位256 (16 * 16) 个元素。</td></tr><tr><td>srcNStride</td><td>源同一NZ矩阵的相邻Z排布的偏移（头与头），取值范围：srcNStride∈[0, 4096]，单位16个元素。</td></tr><tr><td>dstDStride</td><td>目的ND矩阵的相邻行的偏移（头与头），取值范围：dstDStride∈[1, 65535]，单位为元素。</td></tr><tr><td>dstNdMatrixStride</td><td>目的ND矩阵中，来自源相邻NZ矩阵的偏移（头与头），取值范围：dstNdMatrixStride∈[1, 65535]，单位为元素。</td></tr></tbody></table><p>以half数据类型为例，NZ2ND转换示意图如下，样例中参数设置值和解释说明如下：</p><ul><li>ndNum = 2，表示源NZ矩阵的数目为2 (NZ矩阵1为A1~A4 + B1~B4，NZ矩阵2为C1~C4 + D1~D4)。</li><li>nValue = 4，NZ矩阵的行数，也就是矩阵的高度为4。</li><li>dValue = 32，NZ矩阵的列数，也就是矩阵的宽度为32个元素。</li><li>srcNdMatrixStride = 1，表达相邻NZ矩阵起始地址间的偏移，即为A1~C1的距离，即为256个元素(16个DataBlock * 16个元素)。</li><li>srcNStride = 4, 表示同一个源NZ矩阵的相邻Z排布的偏移，即为A1到B1的距离，即为64个元素(4个DataBlock* 16个元素)。</li><li>dstDStride = 160，表达一个目的ND矩阵的相邻行之间的偏移，即A1和A2之间的距离，即为10个DataBlock，即10 * 16 = 160个元素。</li><li>dstNdMatrixStride = 48，表达dst中第x个目的ND矩阵的起点和第x+1个目的ND矩阵的起点的偏移，即A1和C1之间的距离，即为3个DataBlock，3 * 16 = 48个元素。</li></ul><p><strong>图 1</strong> NZ2ND转换示意图（half数据类型）<br><img src="'+s+'" alt="" title="NZ2ND转换示意图（half数据类型）"></p><p>以float数据类型为例，NZ2ND转换示意图如下，样例中参数设置值和解释说明如下：</p><ul><li>ndNum = 2，表示源NZ矩阵的数目为2 (NZ矩阵1为A1~A8 + B1~B8，NZ矩阵2为C1~C8 + D1~D8)。</li><li>nValue = 4，NZ矩阵的行数，也就是矩阵的高度为4。</li><li>dValue = 32，NZ矩阵的列数，也就是矩阵的宽度为32个元素。</li><li>srcNdMatrixStride = 1，表达相邻NZ矩阵起始地址间的偏移，即A1到C1的距离，为256个元素(32个DataBlock * 8个元素)</li><li>srcNStride = 4, 表示同一个源NZ矩阵的相邻Z排布的偏移，即A1到B1的距离，为64个元素 (8个DataBlock * 8个元素)。</li><li>dstDStride = 144，表示一个目的ND矩阵的相邻行之间的偏移，即A1和A3之间的距离，为18个DataBlock，即18 * 8 = 144个元素。</li><li>dstNdMatrixStride = 40，表示dst中第x个目的ND矩阵的起点和第x+1个目的ND矩阵的起点的偏移，即A1和C1之间的距离，为5个DataBlock，5 * 8 = 40个元素。</li></ul><p><strong>图 2</strong> NZ2ND转换示意图（float数据类型）<br><img src="'+r+`" alt="" title="NZ2ND转换示意图（float数据类型）"></p><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>无</p><h2 id="支持的通路和数据类型" tabindex="-1">支持的通路和数据类型 <a class="header-anchor" href="#支持的通路和数据类型" aria-label="Permalink to &quot;支持的通路和数据类型&quot;">​</a></h2><p>下文的数据通路均通过逻辑位置<a href="./../../../其他数据类型/TPosition.html#table5376122715308">TPosition</a>来表达，并注明了对应的物理通路。TPosition与物理内存的映射关系见<a href="./../../../通用说明和约束.html#table07372185712">表1</a>。</p><p><strong>表 4</strong> Local Memory -&gt; Global Memory具体通路和支持的数据类型</p><table tabindex="0"><thead><tr><th>产品型号</th><th>数据通路</th><th>源操作数和目的操作数的数据类型 (两者保持一致)</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>VECOUT -&gt; GM（UB -&gt; GM）</td><td>bool、int8_t、uint8_t、hifloat8_t、fp8_e5m2_t、fp8_e4m3fn_t、fp8_e8m0_t、int16_t、uint16_t、half、bfloat16_t、int32_t、uint32_t、float、complex32、int64_t、uint64_t、double、complex64</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>VECOUT、CO2 -&gt; GM（UB -&gt; GM）</td><td>int16_t、uint16_t、int32_t、uint32_t、half、float</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>VECOUT -&gt; GM（UB -&gt; GM）</td><td>int16_t、uint16_t、int32_t、uint32_t、half、bfloat16_t、float</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>VECOUT -&gt; GM（UB -&gt; GM）</td><td>int16_t、uint16_t、int32_t、uint32_t、half、bfloat16_t、float</td></tr></tbody></table><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>intriParams参数解析请参考<a href="#fig15851251122815">图1</a>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// dstLocal为half类型的LocalTensor，dstGlobal为half类型的GlobalTensor</span></span>
<span class="line"><span>AscendC::Nz2NdParamsFull intriParams{1, 32, 32, 1, 32, 32, 1};</span></span>
<span class="line"><span>// Local Memory -&gt; Global Memory</span></span>
<span class="line"><span>AscendC::DataCopy(dstGlobal, dstLocal, intriParams);</span></span></code></pre></div><p>结果示例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入数据(srcGlobal): [1 2 3 ... 1024]</span></span>
<span class="line"><span>输出数据(dstGlobal):[1 2 ... 15 16 513 514 ... 527 528 17 18 ... 31 32 529 530 ... 543 544 ...497 498 ...  511 512  1009 1010... 1023 1024]</span></span></code></pre></div>`,34)])])}const _=a(i,[["render",n]]);export{b as __pageData,_ as default};
